import { useEffect, useState } from "react";
import { Box, Container, Stack, Typography } from "@mui/material";
import BlocksText from "../components/BlocksText";
import { mediaUrl } from "../services/api";
import type { CarouselSlide } from "../types/home";
import appStoreBadge from "../assets/icons/appstore-apple.png";
import playStoreBadge from "../assets/icons/g-play.png";

const BLUE = "#759ae1";
const APP_STORE_URL = "https://apps.apple.com/in/app/doctutorials-neet-pg-ss-fmge/id1475350376";
const PLAY_STORE_URL = "https://play.google.com/store/apps/details?id=in.dgist.doctutorials&hl=en_US";

type CarouselProps = {
  slides?: CarouselSlide[];
};

export default function Carousel({ slides = [] }: CarouselProps) {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (slides.length < 2) return;
    const timer = window.setInterval(() => {
      setIndex((current) => (current + 1) % slides.length);
    }, 6000);
    return () => window.clearInterval(timer);
  }, [slides.length]);

  const slide = slides[index];
  if (!slide) return null;

  const background = mediaUrl(slide.banner);
  const image = mediaUrl(slide.image);

  return (
    <Box
      sx={{
        position: "relative",
        color: "#fff",
        overflow: "hidden",
        backgroundColor: "#7a9bd7",
        backgroundImage: background ? `url(${background})` : "none",
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      <Box sx={{ position: "absolute", inset: 0, backgroundColor: "rgba(122,155,215,0.45)" }} />
      <Container maxWidth="lg" sx={{ position: "relative", px: { xs: 2, sm: 3, md: 4 }, py: { xs: 4, sm: 5, md: 8 } }}>
        <Stack
          direction={{ xs: "column", md: "row" }}
          alignItems={{ xs: "flex-start", md: "center" }}
          spacing={{ xs: 3, md: 6 }}
        >
          <Box sx={{ flex: 1, width: "100%", maxWidth: { md: 560 } }}>
            <Typography
              component="h1"
              sx={{
                fontSize: { xs: 26, sm: 34, md: 50 },
                fontWeight: 700,
                lineHeight: 1.15,
                mb: { xs: 1, md: 1.5 },
              }}
            >
              {slide.title}
            </Typography>
            <BlocksText
              content={slide.description}
              sx={{
                mb: { xs: 2.5, md: 3 },
                "& p, & h3, & h4, & h5, & h6": {
                  fontSize: { xs: 15, sm: 18, md: 22 },
                  fontWeight: 400,
                  lineHeight: 1.5,
                  mb: { xs: 1.5, md: 2 },
                },
                "& ul": {
                  m: 0,
                  mb: 0,
                  pl: { xs: 2, md: 2.5 },
                },
                "& li": {
                  fontSize: { xs: 14, sm: 16, md: 18 },
                  lineHeight: 1.7,
                  mb: 0.25,
                },
              }}
            />
            <Box
              component="a"
              href="/subscribe"
              sx={{
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                minWidth: { xs: 120, md: 132 },
                height: { xs: 40, md: 44 },
                px: { xs: 2.5, md: 3 },
                backgroundColor: "#ffffff",
                backgroundImage: "none",
                color: BLUE,
                borderRadius: "54px",
                fontSize: { xs: 14, md: 16 },
                fontWeight: 700,
                lineHeight: 1,
                textDecoration: "none",
                boxShadow: "none",
                "&:hover": {
                  backgroundColor: "#ffffff",
                  color: BLUE,
                },
              }}
            >
              Subscribe
            </Box>
            <Stack
              direction="row"
              alignItems="center"
              flexWrap="wrap"
              useFlexGap
              spacing={{ xs: 1, sm: 1.5 }}
              sx={{ mt: { xs: 2, md: 2.5 } }}
            >
              <Box
                component="a"
                href={APP_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Box
                  component="img"
                  src={appStoreBadge}
                  alt="Download on the App Store"
                  sx={{ height: { xs: 34, sm: 40, md: 44 }, width: "auto", display: "block" }}
                />
              </Box>
              <Box
                component="a"
                href={PLAY_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Box
                  component="img"
                  src={playStoreBadge}
                  alt="Get it on Google Play"
                  sx={{ height: { xs: 34, sm: 40, md: 44 }, width: "auto", display: "block" }}
                />
              </Box>
            </Stack>
          </Box>
          {image ? (
            <Box
              sx={{
                flex: 1,
                width: "100%",
                textAlign: "center",
              }}
            >
              <Box
                component="img"
                src={image}
                alt={slide.image?.alternativeText || slide.title}
                sx={{
                  width: "100%",
                  maxWidth: { xs: 360, sm: 420, md: 520 },
                  aspectRatio: { xs: "4 / 3", md: "auto" },
                  objectFit: { xs: "contain", md: "cover" },
                  display: "block",
                  mx: "auto",
                }}
              />
            </Box>
          ) : null}
        </Stack>
      </Container>
      <Stack direction="row" justifyContent="center" spacing={1.25} sx={{ position: "relative", pb: { xs: 2.5, md: 3 } }}>
        {slides.map((item, dotIndex) => (
          <Box
            key={item.id || dotIndex}
            onClick={() => setIndex(dotIndex)}
            sx={{
              width: { xs: 8, md: 10 },
              height: { xs: 8, md: 10 },
              borderRadius: "50%",
              cursor: "pointer",
              backgroundColor: dotIndex === index ? "#fff" : "rgba(255,255,255,0.45)",
            }}
          />
        ))}
      </Stack>
    </Box>
  );
}
